mapper.sql:
WHERE BOARD_TYPE = #{boardType}
  AND DELETED_YN = 'N'

    AND (TITLE LIKE '%' || #{q} || '%' OR WRITER LIKE '%' || #{q} || '%')

mapper.select:
SELECT * FROM (
    SELECT POST_ID, BOARD_TYPE, TITLE, CATEGORY, OPEN_SCOPE, PINNED_YN, VIEW_COUNT,
           WRITER, WRITER_DEPT, CREATED_AT, WRITER_ID
      FROM BOARD_POST

     ORDER BY CASE WHEN PINNED_YN = 'Y' THEN 0 ELSE 1 END, CREATED_AT DESC, POST_ID DESC
) WHERE ROWNUM <= #{limit}

SELECT POST_ID, BOARD_TYPE, TITLE, WRITER, WRITER_ID, DELETED_YN, CREATED_AT
  FROM BOARD_POST
 WHERE POST_ID = #{postId}

mapper.update:
UPDATE BOARD_POST
   SET DELETED_YN = 'Y', DELETED_AT = #{now}, DELETED_BY = #{deletedBy}
 WHERE POST_ID = #{postId}
   AND DELETED_YN = 'N'
